{
  "questions": [
    {
      "stem": "この新技術は医療分野（　）、農業や建築業界でも活用が期待されている。",
      "options": ["にとどまらず", "に限らず", "を越えて", "を通じて"],
      "answer_index": 0,
      "translation_zh": "这项新技术不仅限于医疗领域，在农业和建筑业界也被期待得到应用。",
      "explanation_zh": "「にとどまらず」强调范围扩展至更大领域，符合语境。「に限らず」虽意近但语气较弱；「を越えて」多指跨越界限而非范围延伸；「を通じて」意为“通过”，逻辑不符。",
      "option_explanations_zh": [
        "正确选项：表示不限于某范围而扩展至更广领域，接续名词自然。",
        "干扰项：虽表“不仅限于”，但强调程度不如本考点强烈，语感稍弱。",
        "干扰项：多指跨越物理或抽象界限，此处侧重范围扩大而非跨越。",
        "干扰项：意为“通过……途径”，与后文扩展范围的逻辑不符。"
      ]
    },
    {
      "stem": "彼の影響力は国内（　）、海外の若者にも大きな感銘を与えている。",
      "options": ["にとどまらず", "に限らず", "を抜いて", "に留まって"],
      "answer_index": 0,
      "translation_zh": "他的影响力不仅限于国内，还给海外的年轻人留下了深刻印象。",
      "explanation_zh": "「にとどまらず」突出从较小范围向更大范围的扩展，契合句意。「に限らず」侧重“不限于”但缺乏动态扩展感；「を抜いて」意为“超过”，接续不当；「に留まって」表停滞，与后文矛盾。",
      "option_explanations_zh": [
        "正确选项：准确表达从国内扩展到海外的范围延伸，语意连贯。",
        "干扰项：虽可表不限于某处，但缺乏本考点强调的积极扩展意味。",
        "干扰项：意为“超过”，通常用于比较优劣，此处语境不适用。",
        "干扰项：表示停留在某状态，与后文影响海外的动态事实矛盾。"
      ]
    }
  ]
}
